import { AnimatePresence, motion } from 'framer-motion';
import { Activity, AlertCircle, ArrowRight, ArrowUpRight, CalendarDays, BarChart3, Check, CheckCircle2, ChevronLeft, ChevronRight, Circle, Clock3, Command, Download, FileText, Flag, FolderKanban, LayoutDashboard, ListTodo, LoaderCircle, Menu, MoreHorizontal, Pause, Play, Plus, Search, Settings, Sparkles, Square, Target, Timer, TrendingUp, X } from 'lucide-react';
